import Redis from "ioredis";

const redis = new Redis();

const limit = 100; // max requests allowed per window
const windowMs = 60_000; // 60 second sliding window

/**
 * Sliding-window-log rate limiter backed by a Redis ZSET.
 * One ZSET per user; each granted request is an entry scored by timestamp.
 */
export async function allowRequest(userId: string): Promise<boolean> {
  const key = `ratelimit:${userId}`;
  const now = Date.now();
  const windowStart = now - windowMs;

  const pipeline = redis.multi();

  // Evict entries whose score (timestamp) fell out of the window.
  pipeline.zremrangebyscore(key, 0, windowStart);

  // Record this request. Score = now keeps ordering/eviction correct.
  pipeline.zadd(key, now, now);

  // Count how many entries are currently inside the window.
  pipeline.zcard(key);

  // Let idle keys self-clean once the window has fully elapsed.
  pipeline.expire(key, Math.ceil(windowMs / 1000));

  const results = await pipeline.exec();
  if (!results) {
    throw new Error(`Rate limiter pipeline returned no results for user ${userId}`);
  }

  const [, , zcardResult] = results;
  const [zcardErr, count] = zcardResult;
  if (zcardErr) {
    throw zcardErr;
  }

  return (count as number) <= limit;
}
